 "{seasonClub} évolue désormais en {div} — l'ascension continue.": "{seasonClub} يلعب الآن في {div} — الصعود مستمر.",
 "{seasonClub} change de dimension et rejoint l'élite européenne.": "{seasonClub} يرتقي إلى مستوى آخر وينضم إلى النخبة الأوروبية.",
 "{seasonClub} n'est plus que l'ombre du géant qu'il fut.": "{seasonClub} لم يعد سوى ظل للعملاق الذي كانه.",
