 "{label} : votre carrière s'arrête net en {year}.": "{label}: مسيرتك تتوقف فجأة في {year}.",
 "Retour de blessure réussi en {year} — le pire est derrière vous.": "عودة ناجحة من الإصابة في {year} — الأسوأ أصبح خلفك.",
 "Rechute en {year} : la convalescence s'éternise.": "انتكاسة في {year}: فترة التعافي تطول.",
