 "Prêté une saison à {toClub} pour s'aguerrir.": "إعارة لموسم إلى {toClub} لاكتساب الخبرة.",
 "Retour de prêt convaincant : {parentClub} compte enfin sur vous.": "إعارة مقنعة: {parentClub} يعتمد عليك أخيرًا.",
 "Retour de prêt à {parentClub}, avec une copie honnête.": "العودة من الإعارة إلى {parentClub}، بأداء مقبول.",
 "Un prêt raté : {parentClub} doute ouvertement de vous.": "إعارة فاشلة: {parentClub} يشكك فيك علنًا.",
