 "Élite": "النخبة",
 "Rég.": "إقليمي",
 "Centre d'élite — infrastructures de pointe, concurrence féroce": "أكاديمية نخبة — منشآت متطورة ومنافسة شرسة",
 "Centre professionnel réputé — un cap sérieux vers le haut niveau": "أكاديمية احترافية مرموقة — خطوة جادة نحو المستوى العالي",
 "Club formateur solide — du temps de jeu et de vrais éducateurs": "نادٍ تكويني متين — وقت لعب ومدربون حقيقيون",
 "Club modeste mais structuré — peu de moyens, beaucoup de terrain": "نادٍ متواضع لكنه منظم — إمكانات قليلة ووقت لعب كثير",
 "Petit club discret — loin des projecteurs, mais un vrai tremplin": "نادٍ صغير بعيد عن الأضواء — لكنه منصة انطلاق حقيقية",
 "Club local — l'école de la débrouille, près des vôtres": "نادٍ محلي — مدرسة الاعتماد على النفس، قرب أهلك",
 "En finale !": "في النهائي!",
 "Votre nation renverse tout sur son passage : LA FINALE ! À 90 minutes du toit du monde.": "منتخب بلادك يكتسح كل شيء في طريقه: النهائي! على بعد 90 دقيقة من قمة العالم.",
 "CHAMPION DU MONDE": "بطل العالم",
 "Jeux Olympiques": "الألعاب الأولمبية",
